import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import Header from './components/HeaderHeader';
import Orders from './Orders';

const App = () => {
  return (
    <Router>
      <Header />
      <Routes>
        <Route path="/orders" element={<Orders />} />
        {/* Other routes */}
      </Routes>
    </Router>
  );
};

export default App;
